#define _GNU_SOURCE
#include <stdio.h>
#include <time.h>
#include <sys/syscall.h>
#include <unistd.h>

#define N 10000000L

static double ahora(void) {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec / 1e9;
}

__attribute__((noinline)) long suma_uno(long x) {   /* una función común: no cruza al kernel */
    __asm__ volatile("" : "+r"(x));
    return x + 1;
}

int main(void) {
    volatile long sink = 0;
    struct timespec ts;
    double t0;

    t0 = ahora();
    for (long i = 0; i < N; i++) sink += suma_uno(i);
    printf("función común:        %5.1f ns por llamada\n", (ahora() - t0) / N * 1e9);

    t0 = ahora();
    for (long i = 0; i < N; i++) sink += syscall(SYS_getpid);
    printf("syscall(SYS_getpid):  %5.1f ns por llamada\n", (ahora() - t0) / N * 1e9);

    t0 = ahora();
    for (long i = 0; i < N; i++) { clock_gettime(CLOCK_MONOTONIC, &ts); sink += ts.tv_nsec; }
    printf("clock_gettime:        %5.1f ns por llamada\n", (ahora() - t0) / N * 1e9);
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define N 200000

int main(int argc, char **argv) {
    int directo = argc > 1 && strcmp(argv[1], "directo") == 0;
    FILE *f = fopen("/dev/null", "w");       /* un destino que descarta todo: mide solo el costo de cruzar */
    struct timespec a, b;
    clock_gettime(CLOCK_MONOTONIC, &a);
    for (int i = 0; i < N; i++) {
        if (directo) { if (write(fileno(f), "x", 1) < 0) return 1; }   /* una llamada al sistema por byte */
        else fwrite("x", 1, 1, f);                                      /* la biblioteca acumula en memoria */
    }
    fflush(f);
    clock_gettime(CLOCK_MONOTONIC, &b);
    double ms = (b.tv_sec - a.tv_sec) * 1e3 + (b.tv_nsec - a.tv_nsec) / 1e6;
    fprintf(stderr, "%s: %d bytes en %.1f ms\n", directo ? "write directo" : "fwrite con buffer", N, ms);
    return 0;
}
